function terrainHeight(x,z){const r=Math.hypot(x,z),edge=clamp((84-r)/17,0,1),beach=clamp((r-59)/12,0,1);const hills=8*Math.exp(-((x+15)**2/900+(z+28)**2/550))+12*Math.exp(-((x-30)**2/520+(z+47)**2/420))+5*Math.exp(-((x+47)**2/600+(z+2)**2/800));return -1.5+edge*(.5+Math.sin(x*.09+z*.035)*.65+Math.cos(z*.11)*.38+hills)*(.7+.3*beach)}
const terrainGeo=new THREE.PlaneGeometry(190,190,115,115);terrainGeo.rotateX(-Math.PI/2);const pos=terrainGeo.attributes.position;const colors=[];for(let i=0;i<pos.count;i++){const x=pos.getX(i),z=pos.getZ(i),r=Math.hypot(x,z),y=terrainHeight(x,z);pos.setY(i,y);const c=new THREE.Color(r>66?0xbba676:r>57?0xb3a476:0x668251);c.multiplyScalar(.94+rand()*.12);colors.push(c.r,c.g,c.b)}terrainGeo.setAttribute('color',new THREE.Float32BufferAttribute(colors,3));terrainGeo.computeVertexNormals();const land=new THREE.Mesh(terrainGeo,new THREE.MeshStandardMaterial({vertexColors:true,roughness:1}));land.receiveShadow=true;scene.add(land);
