function makeTree(x,z,scale=1){const g=new THREE.Group(),tr=new THREE.Mesh(new THREE.CylinderGeometry(.28*scale,.45*scale,3.2*scale,7),bark);tr.position.y=1.6*scale;tr.castShadow=true;g.add(tr);const variant=rand();if(variant<.72){for(let j=0;j<3;j++){const crown=new THREE.Mesh(new THREE.ConeGeometry((2.3-j*.35)*scale,(3.2-j*.25)*scale,7),leafMats[Math.floor(rand()*3)]);crown.position.y=(3.1+j*1.35)*scale;crown.castShadow=true;g.add(crown)}}else{const crown=new THREE.Mesh(new THREE.IcosahedronGeometry(2.2*scale,1),leafMats[Math.floor(rand()*3)]);crown.position.y=4.2*scale;crown.castShadow=true;g.add(crown);for(let b=0;b<3;b++){const branch=new THREE.Mesh(new THREE.CylinderGeometry(.07,.12,1.3*scale,5),bark);branch.position.set((b-1)*.52*scale,2.6*scale,0);branch.rotation.z=(b-1)*-.45;g.add(branch)}}addObj('tree',g,x,z,2.5*scale);g.rotation.y=rand()*6.28;return g}
