function showToast(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');toastTimer=2.1}
function nearestResource(max=4.2){let best=null,bd=max;for(const o of objects){if(!o.visible||o.userData.kind==='dino'||o.userData.depleted)continue;const d=player.position.distanceTo(o.position);if(d<bd){bd=d;best=o}}return best}
