 let dragging=false,lastX=0,lastY=0;renderer.domElement.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'&&e.button===0){dragging=true;lastX=e.clientX;lastY=e.clientY;renderer.domElement.setPointerCapture(e.pointerId)}});renderer.domElement.addEventListener('pointermove',e=>{if(dragging){yaw-=(e.clientX-lastX)*.004;pitch=clamp(pitch+(e.clientY-lastY)*.003,-.2,.65);lastX=e.clientX;lastY=e.clientY}});renderer.domElement.addEventListener('pointerup',()=>dragging=false);
 const joy=document.querySelector('#joystick'),knob=document.querySelector('#joyKnob');let joyOn=false,joyVec={x:0,y:0};function setJoy(e){const r=joy.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),limit=r.width*.34,len=Math.hypot(dx,dy),scale=len>limit?limit/len:1;joyVec={x:dx*scale/limit,y:dy*scale/limit};knob.style.transform=`translate(calc(-50% + ${joyVec.x*limit}px),calc(-50% + ${joyVec.y*limit}px))`}
